{
  "items": [
    {
      "title": "Varieties of Democracy (V-Dem) Dataset – Version 16 (2026)",
      "url_or_doi": "https://www.v-dem.net/data/dataset-archive/",
      "justification": "One of the most comprehensive datasets on political systems, democratic institutions, government accountability, political participation, civil liberties, and electoral processes. The 2026 release includes observations through 2025. It provides country-year data suitable for comparing democratic governance across all 36 requested countries and territories, including Kosovo, Moldova, Georgia, Turkey, and the Western Balkans."
    },
    {
      "title": "Quality of Government (QoG) Standard Dataset",
      "url_or_doi": "https://datafinder.qog.gu.se/",
      "justification": "A comprehensive cross-national dataset combining indicators of government effectiveness, corruption, political institutions, democracy, public administration, and institutional quality. Its coverage extends into the 2020s, with data available through 2025 for some indicators. Particularly useful for studying differences in government performance and political institutions across European Union member states and neighboring countries."
    },
    {
      "title": "ParlGov – Parliaments and Governments Database",
      "url_or_doi": "https://www.parlgov.org/data-info/",
      "justification": "Provides structured information about national elections, political parties, cabinet compositions, government coalitions, and parliamentary institutions. Covers European Union countries and several other European democracies. Particularly relevant for comparing government formation, political party representation, and legislative structures during the 2020s. Coverage and update dates vary by country."
    },
    {
      "title": "Representative Democracy Data Archive (REPDEM) – Basic and Election Datasets, Version 2026",
      "url_or_doi": "https://repdem.org/index.php/current-dataset/",
      "justification": "Contains detailed information about parliamentary democracies, political parties, governments, elections, and institutional arrangements. Its 2026 dataset extends through September 30, 2026, and covers 33 parliamentary democracies worldwide. Particularly valuable for examining coalition formation, cabinet duration, government termination, and parliamentary representation in European political systems."
    },
    {
      "title": "Political Parties, Presidents, Elections, and Governments (PPEG) Database",
      "url_or_doi": "https://ppeg.wzb.eu/",
      "justification": "A comparative political dataset covering 73 countries between 1945 and October 2025. Includes political parties, parliamentary elections, presidential elections, government cabinets, ministerial portfolios, and government termination. Useful for analyzing executive-legislative relations, electoral competition, party systems, and government organization in European countries during 2020–2025."
    },
    {
      "title": "Database of Political Institutions (DPI) 2023",
      "url_or_doi": "https://data.iadb.org/dataset/the-database-of-political-institutions-dpi-2023",
      "justification": "Provides annual information on political institutions in more than 180 countries from 1975 to 2023. Variables include executive systems, political party affiliations, government and opposition composition, legislative elections, electoral rules, checks and balances, and decentralization. Particularly useful for comparing institutional structures across the requested countries during 2020–2023."
    },
    {
      "title": "International IDEA – Global State of Democracy Indices, Version 10 (2026)",
      "url_or_doi": "https://www.idea.int/publications/catalogue/html/global-state-democracy-indices-codebook-version-10-2026",
      "justification": "Provides cross-national indicators of democratic performance, political representation, electoral participation, civil liberties, rule of law, and institutional accountability. The 2026 edition covers 1975–2025 and includes the requested European countries, including Kosovo, Moldova, Georgia, Albania, Bosnia and Herzegovina, Montenegro, North Macedonia, Serbia, and Turkey. The linked documentation describes the dataset and its variables."
    },
    {
      "title": "World Bank – Worldwide Governance Indicators (WGI)",
      "url_or_doi": "https://www.worldbank.org/en/publication/worldwide-governance-indicators",
      "justification": "Provides internationally comparable measures of governance across more than 200 economies. Indicators include voice and accountability, political stability, government effectiveness, regulatory quality, rule of law, and control of corruption. Especially useful for comparing government performance, institutional capacity, and governance quality across European Union members, candidate countries, and neighboring states during the 2020s."
    },
    {
      "title": "International IDEA – Voter Turnout Database",
      "url_or_doi": "https://www.idea.int/data-tools/data/voter-turnout-database",
      "justification": "Contains election-level information on voter participation, registered voters, voting-age populations, and turnout in parliamentary, presidential, and European Parliament elections. Covers elections during the 2020s across European countries, making it useful for analyzing electoral participation, democratic engagement, and differences between political systems."
    },
    {
      "title": "Chapel Hill Expert Survey (CHES) – European Political Party Positions, 2024",
      "url_or_doi": "https://www.chesdata.eu/ches-europe/",
      "justification": "Contains expert assessments of European political parties' ideological orientations, positions on European integration, economic policies, social issues, and political competition. The 2024 survey provides contemporary information about party organizations and political alignments. Particularly valuable for comparing party systems and ideological divisions across European countries in the 2020s."
    },
    {
      "title": "European Parliament – 2024 European Election Results and Historical Election Datasets",
      "url_or_doi": "https://results.elections.europa.eu/en/tools/download-datasheets/",
      "justification": "Official European Parliament datasets covering European elections from 1979 through 2024. Includes election results, national party performance, European political group representation, and electoral participation. The 2024 data are particularly relevant for analyzing political organizations, party competition, and parliamentary representation across all 27 European Union member states included in the request."
    },
    {
      "title": "National Elections Data Europe – Harmonized Parliamentary Election Results, 1983–2025",
      "url_or_doi": "https://github.com/schallmeinera/National-Elections-Data-Europe",
      "justification": "Provides geographically harmonized parliamentary election results for 32 European countries, covering 254 elections between 1983 and 2025. Includes party-level results at multiple geographic aggregation levels, including NUTS regions. The dataset incorporates post-2020 elections and is particularly useful for studying regional voting patterns, political party support, electoral competition, and territorial differences in democratic representation."
    },
    {
      "title": "Who Governs Europe – Government Formation and Political Party Systems Database",
      "url_or_doi": "https://whogoverns.eu/",
      "justification": "A comparative database covering governments and party systems across 48 European democracies. Provides information about governing parties, ministerial representation, government formation, and political party system institutionalization. Especially relevant for studying political organizations, coalition governments, and changes in executive power across European countries during the 2020s."
    },
    {
      "title": "Quality of Government Institute – QoG Data Finder, Country-Year Governance Indicators",
      "url_or_doi": "https://datafinder.qog.gu.se/",
      "justification": "An interactive research platform enabling users to identify and download governance-related indicators by country, year, and variable. Includes political institutions, government quality, corruption, democracy, and public-sector performance measures. Particularly useful for creating a customized dataset restricted to the requested countries and years 2020–2025. This is the same research infrastructure as the QoG Standard Dataset but provides a variable-selection interface."
    },
    {
      "title": "International IDEA – Global State of Democracy Indices Technical Procedures Guide, Version 10 (2026)",
      "url_or_doi": "https://www.idea.int/publications/catalogue/html/global-state-democracy-indices-technical-procedures-guide-version-10",
      "justification": "Documents the construction of International IDEA's democracy indicators for 1975–2025. Relevant for researchers developing comparative datasets on democratic representation, political participation, institutional accountability, and civil liberties in the requested countries. This is supporting methodological documentation rather than a separate dataset, and is useful for interpreting the associated democracy indicators."
    }
  ]
}
